/* files below root/rel, depth first in sorted order; 0 or an error result */
static DV *dvz_walk(const char *root, const char *rel, dvz_names *out) {
    char *dir = *rel ? dvz_join(root, rel) : 0;
    const char *at = dir ? dir : root;
    dvz_names names = { 0, 0, 0 };
    int code = dvz_read_dir(at, &names);
    if (code) { DV *e = dvz_err("cannot list directory ", at, 0, 0, code < 0 ? 0 : code); dvz_free(&names); free(dir); return e; }
    DV *err = 0;
    for (size_t i = 0; i < names.n && !err; i++) {
        char *path = *rel ? dvz_join(rel, names.d[i]) : 0;
        const char *r = path ? path : names.d[i];
        char *full = dvz_join(root, r);
        dvz_stat_t st;
        if (DVZ_LSTAT(full, &st) != 0) err = dvz_err("cannot stat ", full, 0, 0, errno);
        else if ((st.st_mode & S_IFMT) == S_IFDIR) err = dvz_walk(root, r, out);
        else if ((st.st_mode & S_IFMT) == S_IFREG) dvz_push(out, r);
        free(full); free(path);
    }
    dvz_free(&names);
    free(dir);
    return err;
}
