/* whole-file copy; returns bytes or -1 with errno */
static int64_t dvz_copy(const char *a, const char *b) {
    FILE *in = fopen(a, "rb");
    if (!in) return -1;
    dvz_stat_t src, dst;
#ifndef _WIN32
    if (fstat(fileno(in), &src) == 0 && DVZ_STAT(b, &dst) == 0 &&
        src.st_dev == dst.st_dev && src.st_ino == dst.st_ino) {
        fclose(in);
        return (int64_t)src.st_size;
    }
#else
    if (strcmp(a, b) == 0 && DVZ_STAT(a, &src) == 0) {
        fclose(in);
        return (int64_t)src.st_size;
    }
#endif
    FILE *out = fopen(b, "wb");
    if (!out) { int code = errno; fclose(in); errno = code; return -1; }
    char buf[65536];
    int64_t total = 0;
    size_t n;
    int code = 0;
    while ((n = fread(buf, 1, sizeof buf, in)) > 0) {
        if (fwrite(buf, 1, n, out) != n) { code = errno ? errno : EIO; break; }
        total += (int64_t)n;
    }
    if (!code && ferror(in)) code = errno ? errno : EIO;
    fclose(in);
    if (fclose(out) != 0 && !code) code = errno ? errno : EIO;
    if (code) { errno = code; return -1; }
    return total;
}
