static void dvo_procs_cleanup(void) {
    for (size_t i = 0; i < dvo_nprocs; i++) {
        dvo_proc *p = &dvo_procs[i];
        if (!p->used) continue;
        if (!p->done) { TerminateProcess(p->h, 1); WaitForSingleObject(p->h, INFINITE); }
        for (int k = 0; k < 3; k++) CloseHandle(p->files[k]);
        CloseHandle(p->h);
        p->used = 0;
    }
}
