/* ---- v0.114: machine floats and float vectors (crate::float) ----
 * Same definitions as float.rs: sequential sums from +0.0, no contraction
 * (compiled with -ffp-contract=off), explicit signed-zero min/max, strict
 * literal grammar, shortest round-trip canonical text. */
#define DVF_VEC_MAX ((size_t)1 << 24)
static DV *dv_text_of(DV *a, const char *op);
static DV *dvf_float(double x) {
    DV *v = dv_new(DV_FLOAT);
    v->u.f = x;
    return v;
}
static double dvf_of(DV *v, const char *op) {
    if (dv_tag(v) != DV_FLOAT) {
        char message[128];
        snprintf(message, sizeof message, "%s expects a Float", op);
        dv_fail(message);
    }
    return v->u.f;
}
static DV *dvf_vec(const double *d, size_t n) {
    DV *v = dv_new(DV_FVEC);
    v->u.fv.d = dv_alloc(sizeof(double) * (n ? n : 1));
    if (n) memcpy(v->u.fv.d, d, sizeof(double) * n);
    v->u.fv.n = n;
    return v;
}
static DV *dvf_vec_take(double *d, size_t n) { DV *v = dvf_vec(d, n); free(d); return v; }
static double *dvf_scratch(size_t n) {
    double *p = malloc(sizeof(double) * (n ? n : 1));
    if (!p) dv_fail("out of memory");
    return p;
}
static DV *dvf_vec_of(DV *v, const char *op) {
    if (dv_tag(v) != DV_FVEC) {
        char message[128];
        snprintf(message, sizeof message, "%s expects a FloatVec", op);
        dv_fail(message);
    }
    return v;
}
static DV *dvf_some_vec(double *d, size_t n) {
    if (n > DVF_VEC_MAX) { free(d); return DV_NONE; }
    return dv_some(dvf_vec_take(d, n));
}
static int dvf_valid_literal(const char *s, size_t n) {
    size_t i = s[0] == '-' ? 1 : 0, start;
    if (n > 4096) return 0;
    start = i; while (i < n && s[i] >= '0' && s[i] <= '9') i++;
    if (i == start) return 0;
    if (i < n && s[i] == '.') { i++; start = i; while (i < n && s[i] >= '0' && s[i] <= '9') i++; if (i == start) return 0; }
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        i++;
        if (i < n && (s[i] == '+' || s[i] == '-')) i++;
        start = i; while (i < n && s[i] >= '0' && s[i] <= '9') i++;
        if (i == start) return 0;
    }
    return i == n;
}
static int dvf_parse(DV *t, double *out) {
    DV *s = dv_text_of(t, "fl_parse");
    if (!dvf_valid_literal(s->u.text.s, s->u.text.n)) return 0;
    *out = strtod(s->u.text.s, 0);
    return 1;
}
/* canonical text from digits d1 d2 ... of d1.d2... x 10^e (float.rs canon) */
static void dvf_canon(int negative, char *digits, int e, dv_buf *b) {
    int n = (int)strlen(digits);
    while (n > 1 && digits[n - 1] == '0') digits[--n] = 0;
    if (negative) dv_buf_str(b, "-");
    if (e >= -5 && e < 17) {
        if (e >= 0) {
            int int_len = e + 1;
            for (int i = 0; i < int_len; i++) { char c[2] = { i < n ? digits[i] : '0', 0 }; dv_buf_str(b, c); }
            dv_buf_str(b, ".");
            if (n > int_len) dv_buf_str(b, digits + int_len); else dv_buf_str(b, "0");
        } else {
            dv_buf_str(b, "0.");
            for (int i = 0; i < -e - 1; i++) dv_buf_str(b, "0");
            dv_buf_str(b, digits);
        }
    } else {
        char c[2] = { digits[0], 0 };
        char exp[16];
        dv_buf_str(b, c);
        dv_buf_str(b, ".");
        dv_buf_str(b, n > 1 ? digits + 1 : "0");
        snprintf(exp, sizeof exp, "e%d", e);
        dv_buf_str(b, exp);
    }
}
static void dvf_text_into(dv_buf *b, double x) {
    if (x != x) { dv_buf_str(b, "nan"); return; }
    if (x == 1.0 / 0.0) { dv_buf_str(b, "inf"); return; }
    if (x == -1.0 / 0.0) { dv_buf_str(b, "-inf"); return; }
    if (x == 0.0) { dv_buf_str(b, signbit(x) ? "-0.0" : "0.0"); return; }
    char s[64];
    for (int p = 0; p < 17; p++) {
        snprintf(s, sizeof s, "%.*e", p, x);
        if (strtod(s, 0) == x) break;
    }
    int negative = s[0] == '-';
    char *body = s + negative, digits[40];
    size_t k = 0;
    char *e = strchr(body, 'e');
    for (char *c = body; c < e; c++) if (*c != '.') digits[k++] = *c;
    digits[k] = 0;
    dvf_canon(negative, digits, atoi(e + 1), b);
}
static double dvf_min(double a, double b) {
    if (a != a) return b;
    if (b != b || a < b) return a;
    if (b < a) return b;
    return signbit(a) ? a : b;
}
static double dvf_max(double a, double b) {
    if (a != a) return b;
    if (b != b || a > b) return a;
    if (b > a) return b;
    return signbit(a) ? b : a;
}
