    dvm_tpair *p = dvv_scratch(sizeof(dvm_tpair) * (n ? n : 1));
    for (size_t i = 0; i < n; i++) { p[i].idx = i; p[i].k = dv_text_of(K->u.list.items[i], "tm_from"); p[i].v = V->u.nv.d[i]; }
    if (n) qsort(p, n, sizeof(dvm_tpair), dvm_tpair_cmp);
