    dvq_poly *ps, *g; size_t n, ng;
    if (!dvq_system(sv, ev, &ps, &n)) return DV_NONE;
    int ok = dvq_basis(ps, n, &g, &ng);
    for (size_t k = 0; k < n; k++) dvq_free(&ps[k]);
    free(ps);
    if (!ok) return DV_NONE;
    dvt_vec out = { 0, 0, 0 };
