    if (!dvq_decode(A->u.nv.d, A->u.nv.n, &x)) return DV_NONE;
    dvt_vec out = { 0, 0, 0 };
    dvq_encode(&x, &out);
    dvq_free(&x);
    return dvt_vec_some(&out);
