/* ---- v0.123: sparse Krylov solvers (crate::sparse) ---- */
static int dvs_setup(DV *rp, DV *ix, DV *vl, DV *bv, double tol, size_t *n, const char *op) {
    DV *b = dvf_vec_of(bv, op);
    if (!dvl_csr(rp, ix, vl, b->u.fv.n, n, op)) return 0;
    return *n == b->u.fv.n && dvl_finite(vl->u.fv.d, vl->u.fv.n) && dvl_finite(b->u.fv.d, *n) && isfinite(tol) && tol >= 0.0;
}
static double dvs_norm(const double *a, size_t n) {
    double square = dvl_dot(a, a, n);
    int zero = 1;
    for (size_t i = 0; i < n; i++) if (a[i] != 0.0) zero = 0;
    if (isfinite(square) && (square > 0.0 || zero)) return sqrt(square);
    double scale = 0.0, sum = 0.0;
    for (size_t i = 0; i < n; i++) scale = fmax(scale, fabs(a[i]));
    if (scale == 0.0 || !isfinite(scale)) return scale;
    for (size_t i = 0; i < n; i++) { double y = a[i] / scale; sum = sum + y * y; }
    return scale * sqrt(sum);
}
static DV *dvs_solution(const nat_t *P, const nat_t *I, const double *V, const double *b, const double *x, size_t n, double tol) {
    if (!dvl_finite(x, n)) return DV_NONE;
    double *r = dvf_scratch(n);
    dvl_spmv(P, I, V, x, n, r);
    for (size_t i = 0; i < n; i++) r[i] = b[i] - r[i];
    int ok = dvl_finite(r, n) && dvs_norm(r, n) <= tol;
    free(r);
    return ok ? dv_some(dvf_vec(x, n)) : DV_NONE;
}
