                    dvy_str(&b, "<image"); dvy_attr(&b, "x", x); dvy_attr(&b, "y", y); dvy_attr(&b, "width", ww); dvy_attr(&b, "height", hh);
                    dvy_str(&b, " preserveAspectRatio=\"none\" style=\"image-rendering:pixelated\" href=\"data:image/png;base64,");
                    dvy_base64(&b, png, len);
                    dvy_str(&b, "\"/>");
