                dvy_attr(&b, "x", x); dvy_attr(&b, "y", y); dvy_attr(&b, "width", ww); dvy_attr(&b, "height", hh);
                dvy_str(&b, "/></clipPath><g clip-path=\"url(#"); dvy_id(&b, "c", ids); dvy_str(&b, ")\">");
