                    r.i += (size_t)cnt;
                    if (ns) {
                        dvy_str(&b, "<path d=\"");
                        for (size_t i = 0; i < ns; i++) {
                            if (i) dvy_str(&b, " ");
                            dvy_str(&b, "M "); dvy_num(&b, segs[i].ax); dvy_str(&b, " "); dvy_num(&b, segs[i].ay);
                            dvy_str(&b, " L "); dvy_num(&b, segs[i].bx); dvy_str(&b, " "); dvy_num(&b, segs[i].by);
                        }
                        dvy_str(&b, "\" fill=\"none\" stroke=\""); dvo_put(&b, val.d, val.n); dvy_str(&b, "\" stroke-opacity=\""); dvo_put(&b, opa.d, opa.n);
                        dvy_str(&b, "\" stroke-width=\""); dvy_num(&b, weight); dvy_str(&b, "\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>");
                    }
