/* draws the window's stored scene into the back buffer; 0 on a malformed scene */
/* MSAA render target of the viewport size (0 samples: draw to the window directly) */
static void dgl_target(dvw_win *x, int vw, int vh) {
    if (dgl_fbo_ok < 0) {
        dgl_fbo_ok = 1;
        for (size_t i = 0; i < sizeof dgl_fbo_names / sizeof dgl_fbo_names[0]; i++) if (!(*dgl_fbo_slot(i) = dgl_proc(dgl_fbo_names[i]))) dgl_fbo_ok = 0;
    }
    if (!dgl_fbo_ok || x->samples < 0) return;
    if (x->fbo && x->fbo_w == vw && x->fbo_h == vh) return;
    if (!x->fbo) {
        int sb = 0, maxs = 0;
        dgl_glGetIntegerv(0x80A8, &sb);           /* SAMPLE_BUFFERS: the window is already multisampled */
        dgl_glGetIntegerv(0x8D57, &maxs);         /* MAX_SAMPLES */
        dgl_glGetError();
        if (sb > 0 || maxs < 2) { x->samples = -1; return; }
        x->samples = maxs < 8 ? maxs : 8;
        dgl_glGenFramebuffers(1, &x->fbo);
        dgl_glGenRenderbuffers(1, &x->rb_color);
        dgl_glGenRenderbuffers(1, &x->rb_stencil);
    }
    dgl_glBindRenderbuffer(0x8D41, x->rb_color);
    dgl_glRenderbufferStorageMultisample(0x8D41, x->samples, 0x8058, vw, vh);     /* RGBA8 */
    dgl_glBindRenderbuffer(0x8D41, x->rb_stencil);
    dgl_glRenderbufferStorageMultisample(0x8D41, x->samples, 0x88F0, vw, vh);     /* DEPTH24_STENCIL8 */
    dgl_glBindFramebuffer(0x8D40, x->fbo);
    dgl_glFramebufferRenderbuffer(0x8D40, 0x8CE0, 0x8D41, x->rb_color);
    dgl_glFramebufferRenderbuffer(0x8D40, 0x821A, 0x8D41, x->rb_stencil);
    int complete = dgl_glCheckFramebufferStatus(0x8D40) == 0x8CD5;
    dgl_glBindFramebuffer(0x8D40, 0);
    if (!complete) {
        unsigned r[2] = { x->rb_color, x->rb_stencil };
        dgl_glDeleteRenderbuffers(2, r);
        dgl_glDeleteFramebuffers(1, &x->fbo);
        x->fbo = 0; x->samples = -1;
        return;
    }
    x->fbo_w = vw; x->fbo_h = vh;
}
static int dgl_draw(dvw_win *x) {
    if (!dgl_current(x)) return 0;
    int ww = x->w > 0 ? x->w : 1, wh = x->h > 0 ? x->h : 1;
    int vw = (int)x->sw, vh = (int)x->sh;
    dgl_h = vh;
    dgl_ramp_tex = x->ramp; dgl_radial_tex = x->radial;
    dgl_target(x, vw, vh);
    dgl_glDisable(0x0C11);                         /* SCISSOR_TEST for the clear */
    dgl_glViewport(0, 0, ww, wh);
    dgl_glClearColor(1, 1, 1, 1);
    dgl_glClearStencil(0);
    dgl_glStencilMask(0xFF);
    dgl_glClear(0x4000 | 0x0400);                  /* COLOR | STENCIL */
    int vy = wh - vh;
    if (x->fbo) {
        dgl_glBindFramebuffer(0x8D40, x->fbo);
        dgl_glViewport(0, 0, vw, vh);
        dgl_glClear(0x4000 | 0x0400);
        vy = 0;
    }
    dgl_glViewport(0, vy, vw, vh);
    dgl_glMatrixMode(0x1701); dgl_glLoadIdentity(); dgl_glOrtho(0, vw, vh, 0, -1, 1);
    dgl_glMatrixMode(0x1700); dgl_glLoadIdentity();
    dgl_glEnable(0x0BE2); dgl_glBlendFunc(0x0302, 0x0303); /* BLEND SRC_ALPHA, ONE_MINUS_SRC_ALPHA */
    dgl_glEnable(0x809D);                          /* MULTISAMPLE */
    dgl_glEnable(0x0C11);
    dvy_ctx *cx = calloc(1, sizeof(dvy_ctx));
    if (!cx) dv_fail("out of memory");
    cx->img = 0; cx->w = (size_t)vw;
    cx->stack[0].x0 = 0; cx->stack[0].y0 = 0; cx->stack[0].x1 = vw; cx->stack[0].y1 = vh;
    dgl_vy = vy;
    int ok = dvy_walk(x->scene, x->scene_n, &x->ss, 2, cx);
    free(cx);
    dgl_glDisable(0x0C11);
    if (x->fbo) {
        /* resolve the samples into the window's back buffer */
        dgl_glBindFramebuffer(0x8CA8, x->fbo);
        dgl_glBindFramebuffer(0x8CA9, 0);
        dgl_glBlitFramebuffer(0, 0, vw, vh, 0, wh - vh, vw, wh, 0x4000, 0x2600);
        dgl_glBindFramebuffer(0x8D40, 0);
        dgl_vy = wh - vh;
    }
    return ok;
}
static DV *dvb_win_gpu(DV *iv) {
    nat_t id = dv_nat_of(iv, "win_gpu");
    dvw_win *x = dvw_get(id);
    if (!x) return dvo_err(-1, "no window %s", dvo_u(id));
    if (!x->gpu) {
        unsigned char *rad=malloc(128*128*4);
        if(!rad)dv_fail("out of memory");
        const char *e = dgl_platform_init(x);
        if(e){free(rad);return dvo_errs(e);}
        unsigned t[2];
        dgl_ramp_tex = 0; dgl_radial_tex = 0;
        dgl_make_textures(rad);
        free(rad);
        t[0] = dgl_ramp_tex; t[1] = dgl_radial_tex;
        x->ramp = t[0]; x->radial = t[1];
        x->gpu = 1;
    }
    const char *ver = (const char *)dgl_glGetString(0x1F02), *ren = (const char *)dgl_glGetString(0x1F01), *ven = (const char *)dgl_glGetString(0x1F00);
    char buf[512];
    snprintf(buf, sizeof buf, "OpenGL %s; %s; %s", ver ? ver : "?", ren ? ren : "?", ven ? ven : "?");
    return dv_result(dv_text(buf, strlen(buf)), 1);
}
static void dgl_keep(dvw_win *x, DV *sc, nat_t w, nat_t h, dvy_scale s) {
    if (x->scene_cap < sc->u.nv.n) {
        nat_t *replacement=malloc(sizeof(nat_t)*(sc->u.nv.n?sc->u.nv.n:1));
        if(!replacement)dv_fail("out of memory");
        free(x->scene);x->scene=replacement;x->scene_cap=sc->u.nv.n;
    }
    if (sc->u.nv.n) memcpy(x->scene, sc->u.nv.d, sizeof(nat_t) * sc->u.nv.n);
    x->scene_n = sc->u.nv.n; x->sw = w; x->sh = h; x->ss = s;
}
/* GPU windows draw the scene with OpenGL (Ok(1)); other windows rasterize on the CPU (Ok(0)) */
static DV *dvb_win_present_scene(DV *iv, DV *sv, DV *wv, DV *hv, DV *nv, DV *dv) {
    nat_t id = dv_nat_of(iv, "win_present_scene");
    DV *sc = dvv_of(sv, "win_present_scene");
    nat_t w = dv_nat_of(wv, "win_present_scene"), h = dv_nat_of(hv, "win_present_scene");
    dvw_win *x = dvw_get(id);
    if (!x) return dvo_err(-1, "no window %s", dvo_u(id));
    dvy_scale s;
    if (!w || !h || w > 16384 || h > 16384 || !dvy_scale_of(nv, dv, "win_present_scene", &s)) return dvo_errs("win_present_scene needs a size up to 16384 and a scale num/den in 1..65536");
    if (!x->gpu) {
        DV *img = dvb_vx_render(sv, wv, hv, nv, dv);
        if (img == DV_NONE) return dvo_errs("invalid scene");
        DV *r = dvb_win_present(iv, img->u.opt.v);
        return r->u.res.ok ? dv_result(dv_nat(0), 1) : r;
    }
    dgl_keep(x, sc, w, h, s);
    if (!dgl_draw(x)) return dvo_errs("invalid scene");
    dgl_swap(x);
    return dv_result(dv_nat(1), 1);
}
/* the last GPU frame read back as an image (drawn again into the back buffer) */
static DV *dvb_win_read(DV *iv) {
    nat_t id = dv_nat_of(iv, "win_read");
    dvw_win *x = dvw_get(id);
    if (!x) return dvo_err(-1, "no window %s", dvo_u(id));
    if (!x->gpu || !x->scene_n) return dvo_errs("win_read needs a GPU window with a presented scene");
    if (!dgl_draw(x)) return dvo_errs("invalid scene");
    size_t w = (size_t)x->sw, h = (size_t)x->sh;
    unsigned char *px = dv_alloc(w * h * 4);
    dgl_glFinish();
    dgl_glReadBuffer(0x0405);                     /* BACK */
    dgl_glPixelStorei(0x0D05, 1);                 /* PACK_ALIGNMENT */
    dgl_glReadPixels(0, dgl_vy, (int)w, (int)h, 0x1908, 0x1401, px);
    nat_t *out = dv_alloc(sizeof(nat_t) * (w * h + 2));
    out[0] = w; out[1] = h;
    for (size_t y = 0; y < h; y++)
        for (size_t xx = 0; xx < w; xx++) {
            const unsigned char *p = px + 4 * ((h - 1 - y) * w + xx);
            out[2 + y * w + xx] = ((nat_t)p[0] << 24) | ((nat_t)p[1] << 16) | ((nat_t)p[2] << 8) | 255u;
        }
    DV *image=dv_new(DV_NVEC);image->u.nv.d=out;image->u.nv.n=w*h+2;return dv_result(image,1);
}
static void dgl_close(dvw_win *x) {
    if (!x->gpu) return;
    if(dgl_current(x)){
    unsigned t[2] = { x->ramp, x->radial };
    dgl_glDeleteTextures(2, t);
    if (x->fbo) {
        unsigned r[2] = { x->rb_color, x->rb_stencil };
        dgl_glDeleteRenderbuffers(2, r);
        dgl_glDeleteFramebuffers(1, &x->fbo);
        x->fbo = 0;
    }
    }
    dgl_platform_close(x);
    free(x->scene);
    x->scene = 0; x->scene_n = x->scene_cap = 0; x->gpu = 0;
}

