/* ---- v0.129: font registry builtins, code points ---- */
static DV *dvb_file_font_load(DV *pv) {
    const char *path;
    if (!dvo_cstr(pv, "file_font_load", &path)) return dvo_named_error("cannot read ", pv, 0, 0);
    if (dvtf_count >= 64) return dvo_errs("too many fonts");
    FILE *fp = fopen(path, "rb");
    if (!fp) { int e = errno; return dvo_err(e, "cannot read `%s`", path); }
    size_t cap = 1 << 16, n = 0;
    unsigned char *d = malloc(cap);
    if (!d) dv_fail("out of memory");
    for (;;) {
        if (n == cap) { cap *= 2; d = realloc(d, cap); if (!d) dv_fail("out of memory"); }
        size_t got = fread(d + n, 1, cap - n, fp);
        n += got;
        if (got == 0) break;
    }
    if (ferror(fp)) { int e = errno; fclose(fp); free(d); return dvo_err(e, "cannot read `%s`", path); }
    fclose(fp);
    dvtf_font f;
    const char *err = dvtf_parse(d, n, &f);
    if (err) { free(d); return dvo_errs(err); }
    dvtf_tab[dvtf_count++] = f;
    return dv_result(dv_nat((nat_t)dvtf_count), 1);
}
static int dvtf_ends_font(const char *lower) {
    size_t n = strlen(lower);
    return n >= 4 && (strcmp(lower + n - 4, ".ttf") == 0 || strcmp(lower + n - 4, ".ttc") == 0);
}
static int dvtf_name_cmp(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }
static char *dvtf_find_in(const char *dir, const char *needle, int depth) {
    if (depth > 8) return 0;
    DIR *dp = opendir(dir);
    if (!dp) return 0;
    char **names = 0;
    size_t n = 0, cap = 0;
    struct dirent *e;
    while ((e = readdir(dp))) {
        if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, "..")) continue;
        if (n == cap) { cap = cap ? cap * 2 : 32; names = realloc(names, sizeof(char *) * cap); if (!names) dv_fail("out of memory"); }
        names[n] = strdup(e->d_name);
        if (!names[n]) dv_fail("out of memory");
        n++;
    }
    closedir(dp);
    if (n) qsort(names, n, sizeof(char *), dvtf_name_cmp);
    char *found = 0;
#ifdef _WIN32
    const char *sep = "\\";
#else
    const char *sep = "/";
#endif
    for (int pass = 0; pass < 2 && !found; pass++)
        for (size_t i = 0; i < n && !found; i++) {
            size_t len = strlen(dir) + strlen(names[i]) + 2;
            char *p = malloc(len);
            if (!p) dv_fail("out of memory");
            snprintf(p, len, "%s%s%s", dir, sep, names[i]);
            struct stat st;
            if (pass == 0) {
                char *lower = strdup(names[i]);
                if (!lower) dv_fail("out of memory");
                for (char *c = lower; *c; c++) if (*c >= 'A' && *c <= 'Z') *c = (char)(*c - 'A' + 'a');
                if (dvtf_ends_font(lower) && strstr(lower, needle) && stat(p, &st) == 0 && S_ISREG(st.st_mode)) { found = p; p = 0; }
                free(lower);
            } else {
#ifdef _WIN32
                int isdir = stat(p, &st) == 0 && S_ISDIR(st.st_mode);
#else
                int isdir = lstat(p, &st) == 0 && S_ISDIR(st.st_mode);
#endif
                if (isdir) found = dvtf_find_in(p, needle, depth + 1);
            }
            free(p);
        }
    for (size_t i = 0; i < n; i++) free(names[i]);
    free(names);
    return found;
}
static DV *dvb_file_font_find(DV *nv) {
    DV *t = dv_text_of(nv, "file_font_find");
    char *needle = malloc(t->u.text.n + 1);
    if (!needle) dv_fail("out of memory");
    for (size_t i = 0; i < t->u.text.n; i++) { char c = t->u.text.s[i]; needle[i] = (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c; }
    needle[t->u.text.n] = 0;
    const char *dirs[8];
    char home1[4096], home2[4096];
    size_t nd = 0;
    const char *h = getenv("HOME");
    if (h) {
        snprintf(home1, sizeof home1, "%s/.local/share/fonts", h); dirs[nd++] = home1;
        snprintf(home2, sizeof home2, "%s/.fonts", h); dirs[nd++] = home2;
    }
    dirs[nd++] = "/usr/share/fonts"; dirs[nd++] = "/usr/local/share/fonts"; dirs[nd++] = "/Library/Fonts"; dirs[nd++] = "/System/Library/Fonts"; dirs[nd++] = "C:/Windows/Fonts";
    char *found = 0;
    for (size_t i = 0; i < nd && !found; i++) found = strlen(needle) == t->u.text.n ? dvtf_find_in(dirs[i], needle, 0) : 0;
    free(needle);
    if (!found) {
        static const char pre[] = "no font file matching `";
        size_t k = sizeof pre - 1, len = k + t->u.text.n + 1;
        char *m = dvv_scratch(len);
        memcpy(m, pre, k);
        memcpy(m + k, t->u.text.s, t->u.text.n);
        m[len - 1] = '`';
        DV *r = dv_result(dv_text(m, len), 0);
        free(m);
        return r;
    }
    DV *r = dv_result(dv_text(found, strlen(found)), 1);
    free(found);
    return r;
}
